from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    Apply at most one rewrite rule to each URL.

    Returns a list containing rewritten URLs, unchanged URLs, or None for
    blocked URLs.
    """
    results = []

    for url in urls:
        parts = urlsplit(url)
        path = parts.path
        matched_rule = None

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            host = parts.hostname or ""

            if match_type == "path_prefix":
                applies = path.startswith(match_value)

            elif match_type == "host":
                if match_value.startswith("*."):
                    domain = match_value[2:]
                    applies = host != domain and host.endswith("." + domain)
                else:
                    applies = host == match_value

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parts.query,
                        keep_blank_values=True
                    )
                }
                applies = match_value in query_names

            else:
                raise ValueError(f"Unknown match_type: {match_type}")

            if applies:
                matched_rule = rule
                break

        if matched_rule is None:
            results.append(url)
            continue

        if matched_rule["action"] == "block":
            results.append(None)
            continue

        action = matched_rule["action"]
        action_value = matched_rule["action_value"]

        if action == "strip_prefix":
            if path.startswith(action_value):
                path = path[len(action_value):]
            if not path:
                path = "/"

            results.append(urlunsplit((
                parts.scheme,
                parts.netloc,
                path,
                parts.query,
                parts.fragment,
            )))

        elif action == "redirect_host":
            # Preserve user information and the original port.
            username = parts.username
            password = parts.password
            port = parts.port

            userinfo = ""
            if username is not None:
                userinfo = username
                if password is not None:
                    userinfo += f":{password}"
                userinfo += "@"

            new_host = action_value
            if ":" in new_host and not new_host.startswith("["):
                new_host = f"[{new_host}]"

            new_netloc = userinfo + new_host
            if port is not None:
                new_netloc += f":{port}"

            results.append(urlunsplit((
                parts.scheme,
                new_netloc,
                parts.path,
                parts.query,
                parts.fragment,
            )))

        elif action == "add_query_param":
            new_query = parts.query
            if new_query:
                new_query += "&"
            new_query += action_value

            results.append(urlunsplit((
                parts.scheme,
                parts.netloc,
                parts.path,
                new_query,
                parts.fragment,
            )))

        else:
            raise ValueError(f"Unknown action: {action}")

    return results
